CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=_user_id AND r.role=_role) AND (_role<>'admin'::public.app_role OR EXISTS(SELECT 1 FROM auth.users u WHERE u.id=_user_id AND u.email_confirmed_at IS NOT NULL AND lower(u.email) IN ('emmanuelvanko@gmail.com','formaeventandsecurity@gmail.com','formaeventandsecuriy@gmail.com'))) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.provider_mission_action(mission_id uuid, action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.portal_records; next_status text; BEGIN SELECT * INTO m FROM public.portal_records WHERE id=mission_id FOR UPDATE; IF auth.uid() IS NULL OR m.id IS NULL OR m.kind<>'mission' OR m.provider_id IS DISTINCT FROM auth.uid() OR NOT EXISTS(SELECT 1 FROM public.portal_roles WHERE user_id=auth.uid() AND role='provider') THEN RAISE EXCEPTION 'Forbidden'; END IF; next_status=CASE WHEN m.status='attribuée' AND action='accept' THEN 'acceptée' WHEN m.status='attribuée' AND action='refuse' THEN 'refusée' WHEN m.status='acceptée' AND action='start' THEN 'en cours' WHEN m.status='en cours' AND action='finish' THEN 'en attente de validation' END; IF next_status IS NULL THEN RAISE EXCEPTION 'Invalid transition'; END IF; UPDATE public.portal_records SET status=next_status,attributes=attributes||jsonb_build_object(action||'_at',now()) WHERE id=mission_id; END $$;